    "summaryZh": "2026-07-10 百度热搜第 15 名，热度 656.5万。近日，广西横州市六蓝水库因台风“美莎克”决堤，洪水冲毁邓圩村养蛇场，约800-900条蛇（含眼镜蛇、大王蛇等）逃入村落，致一名村民被咬伤后因洪水延误治疗离世，村民夜间不敢入睡。捕蛇队已介入排查，当地血清库补足。",
